function rate(user: User): number {
  if (user.age < 18) return 0;
  if (user.age > 65) return 0.5;
  if (user.score > 900) return 0.1;
  if (user.score > 700) return 0.2;
  if (user.score > 500) return 0.3;
  if (user.tenure > 5) return 0.25;
  if (user.tenure > 2) return 0.35;
  return 0.4;
}
