class ReportGenerator {
  generate(type: string, data: any[], fmt: string) {
    let result = '';
    if (type === 'sales') {
      for (const d of data) result += d.product + ',' + d.qty + ',' + d.price + '\n';
    } else if (type === 'inventory') {
      for (const d of data) result += d.sku + ',' + d.stock + '\n';
    }
    if (fmt === 'html') result = '<pre>' + result + '</pre>';
    return result;
  }
}
